use destiny_runtime_core::{Definition,Runtime};use destiny_storage::{InventoryItem,Player};use std::collections::HashMap;use std::sync::Arc;
pub struct InventoryService{pub runtime:Arc<Runtime>,pub players:HashMap<String,Player>}
impl InventoryService{pub fn new(runtime:Arc<Runtime>)->Self{Self{runtime,players:HashMap::new()}}pub fn item_definition(&self,hash:&str)->anyhow::Result<Option<Definition>>{self.runtime.get_definition(hash)}pub fn add(&mut self,player:&str,item_hash:String,quantity:u32,state:String){self.players.entry(player.into()).or_default().inventory.push(InventoryItem{item_hash,quantity,state});}pub fn equipped(&self,player:&str)->Vec<&InventoryItem>{self.players.get(player).map(|p|p.inventory.iter().filter(|i|i.state=="equipped").collect()).unwrap_or_default()}}
